<?php $u=rtrim($_ENV['APP_URL']??'','/');use App\Services\AccessService;$manage=AccessService::can('academico.trayectorias.gestionar'); ?>
<div class="page-head"><div><span class="eyebrow">TRAYECTORIA · <?=htmlspecialchars($student['codigo_estudiante'])?></span><h1><?=htmlspecialchars($student['nombre'])?></h1><p><?=htmlspecialchars($student['numero_identificacion'])?></p></div><a class="btn secondary" href="<?=$u?>/admin/estudiantes/ver?id=<?=$student['id']?>">← Ficha estudiante</a></div>
<?php if($context):?><section class="card"><h2>Antecedente de admisión</h2><dl class="detail-list"><dt>Solicitud</dt><dd><?=htmlspecialchars($context['numero_solicitud'])?></dd><dt>Carrera seleccionada</dt><dd><?=htmlspecialchars($context['carrera']?:'—')?></dd><dt>Sede</dt><dd><?=htmlspecialchars($context['sede']?:'—')?></dd><dt>Modalidad</dt><dd><?=htmlspecialchars($context['modalidad']?:'—')?></dd></dl></section><?php endif;?>
<section class="card"><h2>Trayectorias académicas</h2><div class="table-scroll"><table><thead><tr><th>Carrera</th><th>Malla</th><th>Cohorte</th><th>Sede / modalidad</th><th>Nivel referencial</th><th>Estado</th><th>Inicio</th></tr></thead><tbody><?php foreach($trajectories as $t):?><tr><td><?=htmlspecialchars($t['carrera'])?></td><td><?=htmlspecialchars($t['malla_codigo'].' · '.$t['malla'])?></td><td><?=htmlspecialchars($t['cohorte']?:'—')?></td><td><?=htmlspecialchars(($t['sede']?:'—').' / '.($t['modalidad']?:'—'))?></td><td><?=htmlspecialchars($t['nivel']?:'—')?></td><td><strong><?=htmlspecialchars($t['estado'])?></strong></td><td><?=htmlspecialchars($t['fecha_inicio'])?></td></tr><?php endforeach;?><?php if(!$trajectories):?><tr><td colspan="7" class="empty">Todavía no existe una trayectoria académica formal.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($manage && !$trajectories && $context && $context['carrera_id']):?><section class="card"><h2>Formalizar trayectoria inicial</h2><p class="muted">La carrera, sede y modalidad provienen de la admisión. Selecciona únicamente una malla vigente que permita nuevos estudiantes.</p><?php if(!$curricula):?><div class="notice warn">La carrera seleccionada no tiene una malla vigente habilitada para nuevos estudiantes. Configúrala antes de formalizar la trayectoria.</div><?php else:?><form method="post" action="<?=$u?>/admin/academico/trayectoria/save" class="form-grid"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(\App\Core\Csrf::token())?>"><input type="hidden" name="estudiante_id" value="<?=$student['id']?>"><input type="hidden" name="carrera_id" value="<?=$context['carrera_id']?>"><input type="hidden" name="sede_id" value="<?=$context['sede_id']?>"><input type="hidden" name="modalidad_academica_id" value="<?=$context['modalidad_academica_id']?>"><input type="hidden" name="tipo_ingreso_id" value="<?=$context['tipo_ingreso_id']?>"><label>Malla vigente<select name="malla_id" required><option value="">Seleccione</option><?php foreach($curricula as $m):?><option value="<?=$m['id']?>"><?=htmlspecialchars($m['codigo'].' · '.$m['nombre'].($m['version']?' · '.$m['version']:''))?></option><?php endforeach;?></select></label><label>Cohorte<select name="cohorte_id"><option value="">Sin asignar</option><?php foreach($cohorts as $c):if(!$c['activo'])continue;?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['codigo'].' · '.$c['nombre'])?></option><?php endforeach;?></select></label><label>Estado inicial<select name="estado_trayectoria_id" required><?php foreach($states as $s):?><option value="<?=$s['id']?>" <?=$s['codigo']==='PREMATRICULA'?'selected':''?>><?=htmlspecialchars($s['nombre'])?></option><?php endforeach;?></select></label><label>Nivel referencial<select name="nivel_referencial_id"><option value="">Sin asignar</option><?php foreach($levels as $n):?><option value="<?=$n['id']?>"><?=htmlspecialchars($n['nombre'])?></option><?php endforeach;?></select></label><label>Fecha de inicio<input type="date" name="fecha_inicio" value="<?=date('Y-m-d')?>" required></label><div class="span-2"><button class="btn">Crear trayectoria académica</button></div></form><?php endif;?></section><?php endif;?>
